insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-reports-print-the-tabs-current-s649b','decision','Workplan reports print the tab''s own Current: year cells year-exact, the summary from the Activities tab','The S649 side session, #3268 (c07f0647): the generator works out each project''s Current once. The five per-year cells are year-exact (a year with no Current prints a dash, as the Annual Goals tab does); the summary Current is the Activities tab''s figure (live, else latest recorded), labeled ''latest recorded'' in the report prompt. COBIx''s finding refined the first rule. Undo: git revert.',array['workplan-annual-goals','reports','s649'],'proposed','S649 side session (SkyOriole-B)',null,null,'SkyOriole-B (S649 side session)','2026-11-14'),
('d-identities-rebuild-entries-only-s649b','decision','The identities map rebuild fills and refreshes entries only; 625 held entries wait for Sam','The S649 side session, #3272 (91d451aa): kb/_identities_rebuild.py rebuilds each articulated M-ID''s identities entry by the 1b entry rule (fill 651, refresh 578, held 625; FIRE 130 X 5 to 16 adopters). The records'' leverage fields stay for a measured follow-up because they feed public figures. The apply has NOT run: it waits for Sam''s go and his word on the 625. Receipt and --undo built.',array['commons','identities','m-id','s649'],'proposed','S649 side session (SkyOriole-B)',null,null,'SkyOriole-B (S649 side session)','2026-11-14'),
('d-pages-publish-from-allowlist-s649b','decision','The public site publishes from an allowlist; day one equal, a new top-level path must be decided','The S649 side session, #3278 (6c2cf9a7), on Sam''s #3104 go (''yes to all recommendations'', relayed by COBIx 2026-11-11): pages.yml builds from .github/pages_allowlist.txt. Day one published the same 22,711 files; the first deploy (run 43551846606) succeeded and the pages load. A new path at the root or directly under kb/ needs a publish, publish? or withhold line, or test fails. Undo: git revert.',array['pages','public-site','governance-team-enablement','s649'],'proposed','S649 side session (SkyOriole-B)',null,null,'SkyOriole-B (S649 side session)','2026-11-14'),
('p-workers-commit-refused-go-lives-in-main-session-s649b','pitfall','A worker''s commit can be refused by the permission check; Sam''s go lives in the main conversation','S649 side session: the permission check refused two workers'' git commit (one touching CLAUDE.md, one a data plan), and again after Sam approved, because his words sit in the main conversation, not the worker''s. What worked: show Sam the staged diff; on his word (''commit the bullet'', ''Commit identities'', in session 2026-11-14) the main session commits and the worker pushes.',array['conductor','governance-team-enablement','s649'],'proposed','S649 side session (SkyOriole-B)',null,null,'SkyOriole-B (S649 side session)','2026-11-14'),
('p-two-sessions-one-greeting-side-session-s649b','pitfall','A second session opened with the same handoff greeting runs as a declared side session','2026-11-13 23:52Z: Sam opened a second session with handoff 649''s greeting while the S649 conductor was live. What worked: list_sessions first, one send_message naming files and branches, the newer session takes only lanes the conductor does not hold, branches claude/*-s649b, PR bodies declaring its files and tables, no numbered handoff, a ledger to the conductor. Eight PRs, no collision.',array['conductor','scheduled-sessions','governance-team-enablement','s649'],'proposed','S649 side session (SkyOriole-B)',null,null,'SkyOriole-B (S649 side session)','2026-11-14')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyOriole-B (S649 side session)', 'create', 'side session rows (S649, 2026-11-14)', to_jsonb(m)
from public.cpl_memory m where m.slug in ('d-reports-print-the-tabs-current-s649b','d-identities-rebuild-entries-only-s649b','d-pages-publish-from-allowlist-s649b','p-workers-commit-refused-go-lives-in-main-session-s649b','p-two-sessions-one-greeting-side-session-s649b')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in ('d-reports-print-the-tabs-current-s649b','d-identities-rebuild-entries-only-s649b','d-pages-publish-from-allowlist-s649b','p-workers-commit-refused-go-lives-in-main-session-s649b','p-two-sessions-one-greeting-side-session-s649b')
group by m.slug, m.summary order by m.slug;
